# A small, realistic stack: a private S3 bucket with encryption and versioning, and an IAM policy to read it
variable "env" { type = string }

locals {
  name = "acme-${var.env}-assets"
  tags = { Env = var.env, ManagedBy = "terraform" }
}

resource "aws_s3_bucket" "assets" {
  bucket = local.name
  tags   = local.tags
  lifecycle { prevent_destroy = true }          # accidents must not delete data
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule { apply_server_side_encryption_by_default { sse_algorithm = "aws:kms" } }
}

data "aws_iam_policy_document" "read" {
  statement {
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.assets.arn}/*"]       # least privilege: one bucket, read only
  }
}

resource "aws_iam_policy" "read_assets" {
  name   = "${local.name}-read"
  policy = data.aws_iam_policy_document.read.json
}

output "bucket_name" { value = aws_s3_bucket.assets.id }

# Terraform: a focused IAM role for an ECS task, showing least privilege
data "aws_iam_policy_document" "assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "task" {
  name               = "orders-api-task"
  assume_role_policy = data.aws_iam_policy_document.assume.json   # only ECS tasks may assume it
}

data "aws_iam_policy_document" "task" {
  statement {
    actions   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:Query"]   # not dynamodb:*
    resources = [aws_dynamodb_table.orders.arn, "${aws_dynamodb_table.orders.arn}/index/*"]
  }
  statement {
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.api_key.arn]
  }
}

resource "aws_iam_role_policy" "task" {
  role   = aws_iam_role.task.id
  policy = data.aws_iam_policy_document.task.json
}
